INSERT INTO catechesis_lessons (title, topic, age_group, liturgical_season, lesson_type, objectives, lesson_content, vocabulary_words, discussion_questions, source_attribution) VALUES ('Creation Day 1', 'Creation Day 1', 'Pre K - K', NULL, 'Bible Story', '["identify that God created light on the first day","identify that God separated the light from the darkness","identify that God called the light day and the darkness night"]', '# Lesson Plan- (Pre K - K): Creation Day 1

**Date:** Sunday, September 20, 2009

**Title:** Lesson Plan- (Pre K - K): Creation Day 1

**Objectives:** The children will be able to

- identify that God created light on the first day
- identify that God separated the light from the darkness
- identify that God called the light day and the darkness night

**Review:** Prayer and questions from last week’s lesson.

**Vocabulary Words:**  
[Creation Day 1 Word Wall](https://1drv.ms/b/s!Ar6LKlEjjtdHz3Ps7LOiggUueboW) 

**Plan:**

### Circle Time:

Read story: “Creation Day 1” from your own story book. Then ask questions from below.

- What did God create on the first day? (Light)  
- What did God do with the light? (Separated it from the darkness)  
- What did God call the light? (Day)  
- What did God call the darkness? (Night)  

### Songs and/or Finger Plays:

- [dltk-bible.com - Day 1 Song](http://www.dltk-bible.com/guides/creation-day1-song.htm)  

### Activities:

- [dltk-bible.com - Creation Day 1 Lesson](http://www.dltk-bible.com/guides/creation-day1.htm)  

### Crafts:

- [dltk-bible.com - Light and Dark Craft](http://www.dltk-bible.com/guides/creation-day1-craft.htm)  

### Games:

- [sundayschoolgames.com - Creation Day 1 Game](http://www.sundayschoolgames.com/games/creation-day1.htm)  

### Snacks:

No specific snacks.

